document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".navbar-nav-canvas .bi-chevron-down").forEach(e=>{e.addEventListener("click",function(s){s.preventDefault();const t=e.closest("li").querySelector("ul");if(!t)return;t.classList.contains("show")?(t.style.height="0",t.classList.remove("show"),e.classList.remove("bi-chevron-up"),e.classList.add("bi-chevron-down")):(t.style.height=t.scrollHeight+"px",t.classList.add("show"),e.classList.remove("bi-chevron-down"),e.classList.add("bi-chevron-up"))})}),document.querySelectorAll(".site-nav--has-dropdown ul").forEach(e=>{e.addEventListener("transitionend",()=>{e.classList.contains("show")&&(e.style.height="auto")})})});